 }
 public function authenticated(){return is_user_logged_in();}
 public function mcp_authenticated(){
  $origin=isset($_SERVER['HTTP_ORIGIN'])?esc_url_raw(wp_unslash($_SERVER['HTTP_ORIGIN'])):'';
  if($origin){$host=strtolower((string)wp_parse_url($origin,PHP_URL_HOST));$site=strtolower((string)wp_parse_url(home_url('/'),PHP_URL_HOST));$allowed=$host===$site||$host==='chatgpt.com'||str_ends_with($host,'.chatgpt.com')||$host==='openai.com'||str_ends_with($host,'.openai.com');if(!$allowed)return new WP_Error('invalid_origin','Origin is not allowed.',['status'=>403]);}
