 private function users_delete($r,$p){$id=(int)($p['id']??0);if(!current_user_can('delete_user',$id))return new WP_Error('forbidden','Cannot delete this user.',['status'=>403]);if($id===get_current_user_id())return new WP_Error('self_delete_blocked','Self-deletion is blocked.',['status'=>409]);$ok=$this->confirmed($r,'permanently delete this user');if(is_wp_error($ok))return $ok;require_once ABSPATH.'wp-admin/includes/user.php';return wp_delete_user($id,(int)($p['reassign']??0))?$this->ok(['deleted_id'=>$id]):new WP_Error('failed','Could not delete user.',['status'=>500]);}
 private function themes_list($r,$p){$c=$this->need('switch_themes');if(is_wp_error($c))return $c;$active=wp_get_theme();$items=[];foreach(wp_get_themes() as $slug=>$t)$items[]=['slug'=>$slug,'name'=>$t->get('Name'),'version'=>$t->get('Version'),'active'=>$active->get_stylesheet()===$slug];return $this->ok(['items'=>$items]);}
 private function write_zip($p,$kind){$raw=base64_decode((string)($p['base64_zip']??''),true);if($raw===false||strlen($raw)>30*1024*1024)return new WP_Error('bad_archive','Invalid base64 or archive exceeds 30 MB.',['status'=>400]);if(strlen($raw)<4||substr($raw,0,2)!=='PK')return new WP_Error('bad_archive','The uploaded data is not a ZIP archive.',['status'=>400]);require_once ABSPATH.'wp-admin/includes/file.php';$file=wp_tempnam(sanitize_file_name($p['filename']??$kind.'.zip'));if(!$file||file_put_contents($file,$raw)===false)return new WP_Error('write_failed','Could not write temporary archive.',['status'=>500]);return $file;}
 private function install_zip($file,$kind,$force=false){
  if(!class_exists('ZipArchive'))return new WP_Error('zip_unavailable','PHP ZipArchive is required for remote package installation.',['status'=>500]);
  $zip=new ZipArchive();$opened=$zip->open($file);
  if($opened!==true)return new WP_Error('bad_archive','WordPress could not open the ZIP archive.',['status'=>400,'zip_error'=>$opened]);
  $root='';$invalid=false;
  for($i=0;$i<$zip->numFiles;$i++){
   $stat=$zip->statIndex($i);$name=str_replace('\\','/',$stat['name']??'');
   if($name===''||str_contains($name,"\0")||str_starts_with($name,'/')||preg_match('#^[A-Za-z]:/#',$name)||preg_match('#(^|/)\.\.(/|$)#',$name)){$invalid=true;break;}
   $parts=explode('/',trim($name,'/'));$top=$parts[0]??'';
   if($top===''||($root!==''&&$top!==$root)){$invalid=true;break;}$root=$top;
   if($zip->getExternalAttributesIndex($i,$opsys,$attr)&&((($attr>>16)&0170000)===0120000)){$invalid=true;break;}
  }
  if($invalid||$root===''||sanitize_file_name($root)!==$root){$zip->close();return new WP_Error('unsafe_archive','ZIP must contain one safely named top-level folder and no traversal paths or symbolic links.',['status'=>400]);}
  $base=$kind==='theme'?get_theme_root():WP_PLUGIN_DIR;$target=trailingslashit($base).$root;
  if(file_exists($target)&&!$force){$zip->close();return new WP_Error('destination_exists',ucfirst($kind).' already exists; pass force=true to replace it.',['status'=>409,'slug'=>$root]);}
  if(file_exists($target)&&$force){
   require_once ABSPATH.'wp-admin/includes/file.php';
   global $wp_filesystem;if(!WP_Filesystem()||!$wp_filesystem){$zip->close();return new WP_Error('filesystem_unavailable','WordPress filesystem access is unavailable.',['status'=>500]);}
   if(!$wp_filesystem->delete($target,true)){$zip->close();return new WP_Error('replace_failed','Could not remove the existing package.',['status'=>500]);}
  }
  $done=$zip->extractTo($base);$zip->close();
  if(!$done||!is_dir($target))return new WP_Error('extract_failed','Could not extract the package into WordPress.',['status'=>500]);
  if($kind==='theme'){wp_clean_themes_cache(true);$theme=wp_get_theme($root);if(!$theme->exists())return new WP_Error('invalid_theme','The extracted package is not a valid WordPress theme.',['status'=>400]);return $this->ok(['installed'=>true,'theme'=>$root]);}
  require_once ABSPATH.'wp-admin/includes/plugin.php';wp_clean_plugins_cache(true);$plugins=get_plugins('/'.$root);if(!$plugins)return new WP_Error('invalid_plugin','The extracted package contains no valid WordPress plugin.',['status'=>400]);return $this->ok(['installed'=>true,'plugin'=>$root.'/'.array_key_first($plugins)]);
 }
 private function write_theme_file($p){
  $slug=sanitize_key($p['stylesheet']??'');$relative=str_replace('\\','/',(string)($p['filename']??''));
  if($slug===''||$slug!==($p['stylesheet']??''))return new WP_Error('bad_theme_slug','A safe lowercase stylesheet slug is required.',['status'=>400]);
  if($relative===''||str_contains($relative,"\0")||str_starts_with($relative,'/')||preg_match('#^[A-Za-z]:/#',$relative)||preg_match('#(^|/)\.\.(/|$)#',$relative))return new WP_Error('unsafe_path','Theme file path is unsafe.',['status'=>400]);
  $allowed=['php','css','js','json','txt','md','png','jpg','jpeg','gif','webp','svg','woff','woff2'];$ext=strtolower(pathinfo($relative,PATHINFO_EXTENSION));
  if(!in_array($ext,$allowed,true))return new WP_Error('file_type_blocked','This theme file type is not allowed.',['status'=>400]);
  $raw=base64_decode((string)($p['base64_zip']??''),true);
  if($raw===false||strlen($raw)>10*1024*1024)return new WP_Error('bad_upload','Invalid base64 or theme file exceeds 10 MB.',['status'=>400]);
  $root=trailingslashit(get_theme_root()).$slug;$target=trailingslashit($root).$relative;$parent=dirname($target);
  if(!is_dir($parent)&&!wp_mkdir_p($parent))return new WP_Error('mkdir_failed','Could not create the theme directory.',['status'=>500]);
  if(file_exists($target)&&empty($p['force']))return new WP_Error('destination_exists','Theme file already exists; pass force=true to replace it.',['status'=>409]);
  require_once ABSPATH.'wp-admin/includes/file.php';$tmp=wp_tempnam(basename($target));if(!$tmp||file_put_contents($tmp,$raw,LOCK_EX)===false)return new WP_Error('write_failed','Could not write the temporary theme file.',['status'=>500]);
  if(!@rename($tmp,$target)){if(!@copy($tmp,$target)){@unlink($tmp);return new WP_Error('move_failed','Could not move the theme file into place.',['status'=>500]);}@unlink($tmp);}
  @chmod($target,0644);clearstatcache(true,$target);
  if(!is_file($target)||filesize($target)!==strlen($raw))return new WP_Error('verify_failed','Theme file verification failed.',['status'=>500]);
  require_once ABSPATH.'wp-admin/includes/theme.php';wp_clean_themes_cache(true);return $this->ok(['uploaded'=>true,'theme'=>$slug,'file'=>$relative,'bytes'=>strlen($raw)]);
 }
 private function themes_install($r,$p){$c=$this->need('install_themes');if(is_wp_error($c))return $c;$ok=$this->confirmed($r,'install this theme');if(is_wp_error($ok))return $ok;if(!empty($p['stylesheet'])&&!empty($p['filename'])&&!str_ends_with(strtolower($p['filename']),'.zip'))return $this->write_theme_file($p);$file=$this->write_zip($p,'theme');if(is_wp_error($file))return $file;try{$x=$this->install_zip($file,'theme',!empty($p['force']));}catch(Throwable $e){$x=new WP_Error('installer_exception','Theme installer error: '.$e->getMessage(),['status'=>500]);}@unlink($file);return $x;}
 private function themes_activate($r,$p){$c=$this->need('switch_themes');if(is_wp_error($c))return $c;$ok=$this->confirmed($r,'activate this theme');if(is_wp_error($ok))return $ok;$slug=sanitize_text_field($p['stylesheet']??'');$t=wp_get_theme($slug);if(!$t->exists())return new WP_Error('not_found','Theme not found.',['status'=>404]);switch_theme($slug);return $this->ok(['active_theme'=>wp_get_theme()->get('Name')]);}
