 private function plugins_install($r,$p){$c=$this->need('install_plugins');if(is_wp_error($c))return $c;$ok=$this->confirmed($r,'install this plugin');if(is_wp_error($ok))return $ok;$file=$this->write_zip($p,'plugin');if(is_wp_error($file))return $file;try{$x=$this->install_zip($file,'plugin',!empty($p['force']));}catch(Throwable $e){$x=new WP_Error('installer_exception','Plugin installer error: '.$e->getMessage(),['status'=>500]);}@unlink($file);return $x;}
 private function plugins_activate($r,$p){$c=$this->need('activate_plugins');if(is_wp_error($c))return $c;$ok=$this->confirmed($r,'activate this plugin');if(is_wp_error($ok))return $ok;require_once ABSPATH.'wp-admin/includes/plugin.php';$file=plugin_basename($p['plugin']??'');$x=activate_plugin($file);return is_wp_error($x)?$x:$this->ok(['plugin'=>$file,'active'=>true]);}
 private function plugins_deactivate($r,$p){$c=$this->need('activate_plugins');if(is_wp_error($c))return $c;$ok=$this->confirmed($r,'deactivate this plugin');if(is_wp_error($ok))return $ok;require_once ABSPATH.'wp-admin/includes/plugin.php';$file=plugin_basename($p['plugin']??'');if($file===plugin_basename(__FILE__))return new WP_Error('self_deactivate_blocked','Remote self-deactivation is blocked.',['status'=>409]);deactivate_plugins($file);return $this->ok(['plugin'=>$file,'active'=>false]);}
