 public function regenerate_token(){if(!current_user_can('manage_options'))wp_die('Forbidden');check_admin_referer('wpmcp_regenerate_token');$token='wpmcp_'.wp_generate_password(48,false,false);update_option('wpmcp_token_hash',hash('sha256',$token),false);update_option('wpmcp_service_user',get_current_user_id(),false);set_transient('wpmcp_new_token_'.get_current_user_id(),$token,5*MINUTE_IN_SECONDS);wp_safe_redirect(admin_url('options-general.php?page=wpmcp-manager&generated=1'));exit;}
 public function settings_page(){if(!current_user_can('manage_options'))return;$token=get_transient('wpmcp_new_token_'.get_current_user_id());if($token)delete_transient('wpmcp_new_token_'.get_current_user_id());$service=get_userdata((int)get_option('wpmcp_service_user',get_current_user_id()));?>
  <div class="wrap"><h1>WordPress MCP Manager</h1><p>Connect ChatGPT to this MCP endpoint:</p><p><code style="font-size:14px"><?php echo esc_html(rest_url(self::NS.'/mcp')); ?></code></p><?php if($token): ?><div class="notice notice-warning inline"><p><strong>Copy this bearer token now. It will not be shown again.</strong></p><p><input type="text" readonly value="<?php echo esc_attr($token); ?>" style="width:100%;max-width:760px" onclick="this.select()"></p></div><?php endif; ?><p>The token acts with the permissions of: <strong><?php echo esc_html($service?$service->user_login:'not configured'); ?></strong></p><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="wpmcp_regenerate_token"><?php wp_nonce_field('wpmcp_regenerate_token'); ?><?php submit_button(get_option('wpmcp_token_hash')?'Regenerate bearer token':'Generate bearer token','primary'); ?></form><p>Regenerating immediately invalidates the previous token.</p></div>
 <?php }
